import random, numpy as np
for typ in ['pyshuffle_inv','pysample_inv','rs_inv','default_inv']:
 found={q:None for q in ['TR','BL','BR']}
 for seed in range(50000):
  if typ.startswith('pyshuffle'):
   p=list(range(64));random.Random(seed).shuffle(p)
  elif typ.startswith('pysample'):
   p=random.Random(seed).sample(range(64),64)
  elif typ.startswith('rs'):
   p=np.random.RandomState(seed).permutation(64)
  else:p=np.random.default_rng(seed).permutation(64)
  inv=np.argsort(p)
  for q,(dr,dc) in {'TR':(0,8),'BL':(8,0),'BR':(8,8)}.items():
   if found[q] is not None: continue
   if all(o3[dr+r][dc+c]==i3[inv[r*8+c]//8][inv[r*8+c]%8] and o5[dr+r][dc+c]==i5[inv[r*8+c]//8][inv[r*8+c]%8] for r in range(8) for c in range(8)):
    found[q]=seed
 print(typ,found)

